"""Read the SLO file, and write generated files."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

import yaml

from capacity.application import rules
from capacity.domain.errors import InvalidSloError
from capacity.domain.slo import BurnAlert, SliKind, Slo


@dataclass(frozen=True, slots=True)
class JourneyDoc:
    """A journey's rank and its one-sentence definition of working."""

    name: str
    rank: int
    working: str


@dataclass(frozen=True, slots=True)
class SloSpec:
    """Everything `slo/slos.yaml` defines."""

    window_days: int
    journeys: tuple[JourneyDoc, ...]
    slos: tuple[Slo, ...]
    alerts: tuple[BurnAlert, ...]


def _load(path: Path) -> dict[str, Any]:
    with path.open(encoding="utf-8") as handle:
        document = yaml.safe_load(handle)
    if not isinstance(document, dict):
        raise InvalidSloError(f"{path} must contain a mapping")
    return document


def load_spec(path: Path) -> SloSpec:
    """Parse `slos.yaml`; any missing or inconsistent field raises InvalidSloError."""
    document = _load(path)
    try:
        window_days = int(document["window_days"])
        journeys = tuple(
            JourneyDoc(name, int(body["rank"]), str(body["working"]).strip())
            for name, body in document["journeys"].items()
        )
        slos = tuple(
            Slo(
                name=entry["name"],
                journey=entry["journey"],
                kind=SliKind(entry["kind"]),
                target=float(entry["target"]),
                valid=str(entry["valid"]).strip(),
                good=str(entry["good"]).strip(),
                why=str(entry["why"]).strip(),
                threshold_ms=float(entry["threshold_ms"]) if "threshold_ms" in entry else None,
                window_days=window_days,
            )
            for entry in document["slos"]
        )
        default_guard = int(document.get("min_bad_events", 10))
        alerts = tuple(
            BurnAlert(
                e["name"],
                e["severity"],
                float(e["factor"]),
                int(e["long_minutes"]),
                int(e["short_minutes"]),
                int(e.get("min_bad_events", default_guard)),
            )
            for e in document["alerts"]
        )
    except (KeyError, TypeError, ValueError) as error:
        raise InvalidSloError(f"{path}: {error!r}") from error
    known = {journey.name for journey in journeys}
    unknown = {slo.journey for slo in slos} - known
    if unknown:
        raise InvalidSloError(f"{path}: SLOs reference undefined journeys {sorted(unknown)}")
    return SloSpec(window_days, journeys, slos, alerts)


def _literal_for_multiline(dumper: yaml.SafeDumper, value: str) -> yaml.ScalarNode:
    style = "|" if "\n" in value else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", value, style=style)


class _RuleDumper(yaml.SafeDumper):
    """Dump multi-line expressions as literal blocks so the generated file reads like hand-written rules."""


_RuleDumper.add_representer(str, _literal_for_multiline)


def dump_rules(document: dict[str, Any], header: str) -> str:
    """Serialize a rule document with a generated-file banner."""
    body = yaml.dump(document, Dumper=_RuleDumper, sort_keys=False, width=10_000, allow_unicode=True)
    return "".join(f"# {line}\n" for line in header.splitlines()) + body


DEMO_WINDOW_SCALE = 60.0
BANNER = "Generated by `capacity-slo rules` from slo/slos.yaml. Do not edit; `make rules-check` fails on drift."


def render_rule_files(spec: SloSpec) -> dict[Path, str]:
    """The production and demo Prometheus rule files, as relative path to text."""
    production = rules.build_rules(spec.slos, spec.alerts, 1.0, "", "30s")
    demo = rules.build_rules(spec.slos, spec.alerts, DEMO_WINDOW_SCALE, "demo", "1s")
    return {
        Path("slo/generated/rules.yml"): dump_rules(production, BANNER + "\nProduction profile."),
        Path("slo/generated/rules.demo.yml"): dump_rules(
            demo, BANNER + f"\nDemo profile: every window divided by {DEMO_WINDOW_SCALE:g}."
        ),
    }


_FLEET_RULES = """# The capacity plan as an alert. The plan says {peak} healthy instances are needed to carry the projected peak at the
# measured safe load (tests/unit/test_evidence.py keeps this number equal to the plan's evidence). Below {peak}
# the fleet cannot meet the SLO at peak even though no request has failed yet.
# Generated by `capacity plan` from docs/evidence/plan.json. Do not edit.
groups:
  - name: fleet-capacity
    interval: 2s
    rules:
      - alert: FleetBelowPeakCapacity
        expr: envoy_cluster_membership_healthy{{envoy_cluster_name="app"}} < {peak}
        for: 10s
        labels:
          severity: page
          service: app
        annotations:
          summary: Fewer than {peak} healthy instances, which is the minimum that carries the projected peak
          description: A zone may be down. At the projected peak the surviving instances are above their safe load.
          runbook_url: docs/runbooks/zone-loss.md
      - alert: FleetBelowFullStrength
        expr: envoy_cluster_membership_healthy{{envoy_cluster_name="app"}} < {total}
        for: 30s
        labels:
          severity: ticket
          service: app
        annotations:
          summary: At least one instance is unhealthy; the fleet has lost some of its headroom
          description: Capacity is still enough for peak while {peak} or more are healthy, but another loss may not be.
          runbook_url: docs/runbooks/zone-loss.md
"""  # noqa: E501

_FLEET_TESTS = """# The capacity plan as an alert: {peak} healthy instances carry the projected peak, so fewer than {peak} pages and
# fewer than {total} (any loss of headroom) opens a ticket. Samples step every 2 seconds, like the scrape interval.
# Generated by `capacity plan` from docs/evidence/plan.json. Do not edit.
rule_files:
  - ../alerts/fleet.rules.yml

evaluation_interval: 2s

tests:
  - name: losing a zone leaves {survivors}, which is a ticket and not a page
    interval: 2s
    input_series:
      - series: 'envoy_cluster_membership_healthy{{envoy_cluster_name="app"}}'
        values: "{total}x9 {survivors}x39 {total}x30"
    alert_rule_test:
      - eval_time: 60s
        alertname: FleetBelowFullStrength
        exp_alerts:
          - exp_labels: {{severity: ticket, service: app, envoy_cluster_name: app}}
            exp_annotations:
              summary: At least one instance is unhealthy; the fleet has lost some of its headroom
              description: Capacity is still enough for peak while {peak} or more are healthy, but another loss may not be.
              runbook_url: docs/runbooks/zone-loss.md
      - {{eval_time: 60s, alertname: FleetBelowPeakCapacity, exp_alerts: []}}
      - {{eval_time: 140s, alertname: FleetBelowFullStrength, exp_alerts: []}}

  - name: {short} healthy instances cannot carry the peak and page
    interval: 2s
    input_series:
      - series: 'envoy_cluster_membership_healthy{{envoy_cluster_name="app"}}'
        values: "{total}x9 {short}x39 {total}x30"
    alert_rule_test:
      - eval_time: 40s
        alertname: FleetBelowPeakCapacity
        exp_alerts:
          - exp_labels: {{severity: page, service: app, envoy_cluster_name: app}}
            exp_annotations:
              summary: Fewer than {peak} healthy instances, which is the minimum that carries the projected peak
              description: A zone may be down. At the projected peak the surviving instances are above their safe load.
              runbook_url: docs/runbooks/zone-loss.md
      - {{eval_time: 140s, alertname: FleetBelowPeakCapacity, exp_alerts: []}}

  - name: a one-sample dip does not page
    interval: 2s
    input_series:
      - series: 'envoy_cluster_membership_healthy{{envoy_cluster_name="app"}}'
        values: "{total}x9 {short} {total}x30"
    alert_rule_test:
      - {{eval_time: 24s, alertname: FleetBelowPeakCapacity, exp_alerts: []}}
"""  # noqa: E501


def render_fleet_files(instances_for_peak: int, total: int, survivors: int) -> dict[Path, str]:
    """The fleet alert rules and their promtool replay for a plan of `total` instances, `instances_for_peak` needed."""
    values = {"peak": instances_for_peak, "total": total, "survivors": survivors, "short": instances_for_peak - 1}
    return {
        Path("slo/alerts/fleet.rules.yml"): _FLEET_RULES.format(**values),
        Path("slo/tests/fleet.test.yml"): _FLEET_TESTS.format(**values),
    }
